                module Action
                module StepTimedRecordDecay
                ; Документация [алгоритм и проверка](../../Docs/ActionTimedDecayState.md)
                ; -----------------------------------------
                ; Декремент времени состояния, освобождение при истечении и деление управляющего байта на два
                ; исходная запись 17, адреса F66A..F67E
                ; In:
                ;   HL, DE, BC числовых аргументов не задают, AF содержит сохраняемый A и Carry для прямого освобождения
                ;   IX указывает FActionRecord, Unknown11 и OffsetScaleLow доступны, при освобождении доступны Component0 и ReuseByte
                ;   читается Component0.High, для активной записи доступны остальные фазовые поля, класс, состояние и порог
                ;   OffsetScaleLow и OffsetScaleHigh активной записи доступны для записи, ACTION банка 0 и общая RAM доступны
                ;   действует договор ApplyObjectOffsetVector, шесть байтов под SP и внешний возврат не перекрывают его код, таблицы, операнды и результаты
                ;   IRQ и повторный вход исключены
                ; Out:
                ;   при исходном Unknown11=1 после записи нуля выполняется реальный MarkRecordForReuse и внешний RET, SP=входной SP+2, R получает 10 M1
                ;   на прямом освобождении A сохраняется, F=42 OR входной Carry, прочие регистры сохранены, Component0=8000 и ReuseByte=FF
                ;   все последующие эффекты общего хвоста относятся только к исходному Unknown11 не равному 1
                ;   при маркере Component0.High=80 общий хвост даёт AF=8042, прочие регистры кроме R сохранены, собственные Unknown11 и половина масштаба не откатываются
                ;   на активной ветви нижеследующие результаты вычислителя относятся к V из прежнего OffsetScaleLow и выбранного старшего байта
                ;   HL=(-Q) AND FFFF при бите 7 S=1, иначе HL=Q, DE=Q при бите 7 S=1, иначе DE=abs(V)
                ;   BC - B=W[Offset0], C=0
                ;   AF - A=S, F от 16-разрядного 0-Q при бите 7 S=1, иначе флаги логического XOR с результатом S
                ;   HL', DE', BC' сохраняются
                ;   AF' - A'=U, F'=(U AND 28) OR (40 при U=0) OR (10 при 2*((P SHR 16) AND 0F)+(U AND 1)>0F), остальные биты F' нулевые
                ;   IX восстановлен, IYH сохраняется, IYL=W[(Offset1+64) AND FF]
                ;   Coefficient0..2 содержат результат построителя, Base0..2 содержат три произведения с одним входным V
                ;   SP=входной SP+2, I, IM, IFF и paging сохраняются, порты не используются
                ;   Offset0..2 получают OffsetPhase0, wrap8(OffsetPhase1+80) и OffsetPhase2
                ;   OffsetScaleHigh обнулён при ClassCode<10 и StateCode не равном 13, иначе сохранён
                ;   на активной ветви общий хвост добавляет к R 30+Hold+4*Small+2*Small*Different M1 подготовки плюс полный вычислитель, старший бит R сохраняется
                ;   Unknown11 всегда уменьшается по модулю 256, при прямом освобождении прежний OffsetScaleLow не изменяется
                ;   на неистёкшей ветви h=floor(c/2), где c исходный OffsetScaleLow, ненулевой c сначала записывает h, нулевой c собственной записи не создаёт
                ;   на активной неистёкшей ветви OffsetScaleLow получает h+1, если h+1<Phase2OrTarget, иначе h, текущий вычислитель использует E=h
                ;   на неистёкшем маркере окончательный OffsetScaleLow равен h, общая прибавка не выполняется
                ;   собственный префикс неистёкшего пути даёт 7 M1 при c=0 и 12 при c!=0, затем прибавляется полный общий хвост
                ;   I/IM/IFF и paging сохраняются на всех путях, OUT отсутствует
                ; Corrupt:
                ;   HL, DE, BC, AF, AF', IYL, R, Coefficient0..2, Base0..2 и шесть временных байтов CPU-стека, три фазовых операнда и условно OffsetScaleLow/OffsetScaleHigh, Unknown11, условно Component0 и ReuseByte
                ;   прямое освобождение не вызывает вычислитель и не пишет CPU-стек, маркер не отменяет собственные записи перед F0F8
                ; Note:
                ;   это исходная цель State07, общий смысл физического Unknown11 для иных состояний не переопределяется
                ;   42, 8000 и FF в маркерных результатах шестнадцатеричные, h+1 не оборачивается, поскольку h<=127
                ;   половина является входом общего хвоста, поэтому окончательный масштаб может увеличиться относительно исходного нуля или совпасть с исходным 1 либо 2
                ;   эффективное слово V перед 6D06 содержит прежний OffsetScaleLow в E и итоговый OffsetScaleHigh в D, это не входное DE всей процедуры
                ;   Hold=1 при сохранении прежнего младшего масштаба, иначе 0, Small=1 при ClassCode<10, Different=1 при StateCode не равном 13, иначе соответствующий признак нулевой
                ;   10, 13 и 80 в условиях полей обозначают шестнадцатеричные коды, числа M1 десятичные
                ;   c2 обозначает третий байтовый коэффициент, m=abs(s8(c2)) AND 7F, P=m*abs(V), Q=floor(P/128), U=P SHR 15, S=c2 XOR HIGH слова V
                ;   нулевой фактор для коэффициента 80 сохранён, знак определяется исходным байтом коэффициента и старшим байтом V
                ;   каждое Base равно -floor((abs(s8(c_i)) AND 7F)*abs(V)/128) при бите 7 c_i XOR HIGH V, иначе положительному частному, всё по модулю 65536
                ;   шесть временных байтов после возврата содержат исходный IX по SP-2, слово V по SP-4 и внутренний возврат 6D0C по SP-6, POP не очищает RAM
                ;   для фактора m>0 умножение даёт 35+floor(log2(m))+2*popcount(m) M1, при m=0 даёт 32 M1
                ;   к каждому умножению добавляются семь M1 при V<0, две при бите 7 коэффициента и четыре при бите 7 его XOR HIGH V
                ;   маркер внутри F0F8 возвращается до записи общих фазовых операндов и не вызывает вычислитель, на активном пути внешний RET выполняет его хвост
                ;   отдельная проверка F0F8, 196608 прежних сценариев останавливаются перед 6D06 либо на раннем RET, новая композиция проверяет 15616 случаев до полного внешнего возврата
                ;   полное произведение всех аргументов, точные T, IRQ и нативная игра не доказаны
                ;   131072 прежних случая проверяют собственный префикс и реальное освобождение, 24576 новых случаев этого входа продолжаются до полного RET
                ;   полная новая композиция двух таймерных входов имеет 49152 случая, проверены регистры включая R, восемь банков, кратность записей и отсутствие OUT
                ;   физические единицы масштаба, полное произведение входов, точные T, IRQ и нативный запуск не доказаны
                ; -----------------------------------------
                ; Обновление счётчика состояния по модулю 256, истечение наступает только при исходной единице.
Entry:          DEC (IX + @FActionRecord.Unknown11)
                JP Z, @Action.MarkRecordForReuse.Entry                          ; переход, если после декремента Unknown11 равен нулю, освободить текущую запись с внешним RET

                ; Проверка управляющего байта перед беззнаковым затуханием.
                LD A, (IX + @FActionRecord.OffsetScaleLow)
                AND A
                JP Z, @Action.PrepareObjectOffsetTransform.Entry                ; переход, если OffsetScaleLow равен нулю, сохранить его и продолжить общий хвост

                ; Расчёт целой половины OffsetScaleLow, его прежний младший бит становится Carry.
                SRL A
                ; Обновление управляющего байта рассчитанной половиной.
                LD (IX + @FActionRecord.OffsetScaleLow), A
                JP @Action.PrepareObjectOffsetTransform.Entry

                endmodule
                endmodule
